#!/bin/bash
#
# acceptance-core-loop.sh — the CORE_LOOP sign-off gate (Docs/Design/CORE_LOOP.md, S24).
#
# Runs Tests/CoreLoop: one automated end-to-end walk of the loop — open, calibrate, measure,
# export, undo — on a heavy A1 roof plan, driving the same presenters the UI binds to and the
# same engines the app ships. The sheet is the Synthetic Roof Plan of ZPDFTestingSupport
# (Packages/ZPDFTestingSupport/FIXTURES.md): generated by the test itself, byte for byte the
# same on every machine, so the gate runs on any clone. Green here plus a maintainer's own
# hands-on approval is what signs the loop off; neither alone does.
#
# Gates:
#
#   1. The sheet's versioned identity: the identity name and SHA-256 pinned here must be the
#      ones the generator pins (SyntheticRoofPlan.version / .sha256), and the test prints the
#      digest of the file it actually generated and walked — the gate must not run against a
#      different drawing and call it the same sign-off. A generator change that moves one
#      byte bumps the version and every pin with it.
#   2. swift build --build-tests, then swift test with xunit accounting: executed counts
#      come from the runner's own --xunit-output XML via Scripts/xunit-summary.sh, with the
#      non-vacuity floor. Skipped tests are failures.
#   3. Declared @Test count equals the executed count.
#   4. Named proof obligations: every CORE-LOOP step marker must appear in the output —
#      OPEN, CALIBRATE (4 actions), MEASURE, LEDGER, EXPORT (3+3 actions), GUARDS, UNDO,
#      and the two fresh-document guards. A green suite that quietly lost a step is red.
#   5. No skipped, disabled or compiled-out tests in the package.
#
# Exits non-zero on the first failure, naming the phase.

set -u
set -o pipefail

readonly ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

# --- Who holds the tree -----------------------------------------------------------------------
#
# Two builds sharing one working tree and one `.build` interfere with each other, and nothing
# else records that the other one is there. `wave-marker.sh check` prints a warning when another
# run's fresh marker is present, and **always exits 0**: a marker is a convention, never a lock,
# and a leftover one must not be able to redden or wedge a gate. Stale markers expire.
if [ -x "${ROOT}/Scripts/wave-marker.sh" ]; then
    "${ROOT}/Scripts/wave-marker.sh" check Apps Packages
fi

readonly PACKAGE_DIR="${ROOT}/Tests/CoreLoop"
readonly GENERATOR="${ROOT}/Packages/ZPDFTestingSupport/Sources/ZPDFTestingSupport/Fixtures/SyntheticRoofPlan.swift"
readonly FIXTURE_VERSION="1"
readonly FIXTURE_IDENTITY="synthetic-roof-plan/${FIXTURE_VERSION}"
readonly FIXTURE_SHA256="424c2fad6aa7284bcdc410d9c209c24d10e7eac8b4d1027dd4fd1b2952295d44"
# A run that must not share `.build` with other builds passes its own scratch path
# (see `Scripts/wave-marker.sh`, who holds the tree). Empty means SwiftPM's default.
readonly SCRATCH_PATH="${ZENIT_CORE_LOOP_SCRATCH_PATH:-}"
SCRATCH_FLAGS=()
if [ -n "${SCRATCH_PATH}" ]; then SCRATCH_FLAGS=(--scratch-path "${SCRATCH_PATH}"); fi

fail() {
    printf '\nFAILED: CORE_LOOP acceptance during %s\n' "$1" >&2
    exit 1
}

# --- Testing.framework search paths (same reasoning as build-appcore-package.sh) -------------

DEVELOPER_DIR_CANDIDATES=(
    "$(xcode-select -p 2>/dev/null || true)"
    "/Library/Developer/CommandLineTools"
)
TESTING_FRAMEWORKS=""
TESTING_LIBS=""
for candidate in "${DEVELOPER_DIR_CANDIDATES[@]}"; do
    [ -n "${candidate}" ] || continue
    # Full Xcode keeps the framework in its macOS platform; the Command Line Tools keep it at
    # the top level. Each entry is "<frameworks dir>:<lib dir>" relative to the candidate.
    for layout in \
        "Platforms/MacOSX.platform/Developer/Library/Frameworks:Platforms/MacOSX.platform/Developer/usr/lib" \
        "Library/Developer/Frameworks:Library/Developer/usr/lib"; do
        if [ -d "${candidate}/${layout%%:*}/Testing.framework" ]; then
            TESTING_FRAMEWORKS="${candidate}/${layout%%:*}"
            TESTING_LIBS="${candidate}/${layout##*:}"
            break 2
        fi
    done
done
readonly TESTING_FRAMEWORKS
readonly TESTING_LIBS
if [ -z "${TESTING_FRAMEWORKS}" ]; then
    printf 'FAIL: no Testing.framework found; swift-testing is required.\n' >&2
    exit 1
fi
printf 'Testing.framework: %s\n' "${TESTING_FRAMEWORKS}"

readonly TEST_FLAGS=(
    -Xswiftc -F -Xswiftc "${TESTING_FRAMEWORKS}"
    -Xlinker -F -Xlinker "${TESTING_FRAMEWORKS}"
    -Xlinker -rpath -Xlinker "${TESTING_FRAMEWORKS}"
    -Xlinker -rpath -Xlinker "${TESTING_LIBS}"
)

# --- Gate 1: the sheet's versioned identity --------------------------------------------------
#
# The file is generated inside the test run, so there is nothing on disk to hash yet. What can
# be checked before building is that this gate and the generator pin the same identity; the
# digest of the file actually walked is checked after the run, through the OPEN marker below.

[ -f "${GENERATOR}" ] || fail "fixture check (no generator at '${GENERATOR}')"
grep -qE "public static let version = ${FIXTURE_VERSION}\$" "${GENERATOR}" \
    || fail "fixture check (the generator is not at version ${FIXTURE_VERSION}; re-pin this gate with it)"
grep -qF "public static let sha256 = \"${FIXTURE_SHA256}\"" "${GENERATOR}" \
    || fail "fixture check (the generator pins another digest than ${FIXTURE_SHA256:0:12}...; re-pin this gate with it)"
printf 'Fixture: %s (sha256 %s..., generated by the test)\n' "${FIXTURE_IDENTITY}" "${FIXTURE_SHA256:0:12}"

[ -f "${PACKAGE_DIR}/Package.swift" ] || fail "package check (no Package.swift at ${PACKAGE_DIR})"
cd "${PACKAGE_DIR}" || fail "cd"

# --- Gate 2: build, then test with machine-readable accounting -------------------------------

printf '\n=== CoreLoopAcceptance : swift package resolve ===\n'
swift package resolve ${SCRATCH_FLAGS[@]+"${SCRATCH_FLAGS[@]}"} || fail "swift package resolve"

printf '\n=== CoreLoopAcceptance : swift build --build-tests ===\n'
swift build ${SCRATCH_FLAGS[@]+"${SCRATCH_FLAGS[@]}"} --build-tests "${TEST_FLAGS[@]}" || fail "swift build --build-tests"

printf '\n=== CoreLoopAcceptance : swift test ===\n'
test_log="$(mktemp)" || fail "mktemp"
xml_dir="$(mktemp -d)" || fail "mktemp -d"
if ! swift test ${SCRATCH_FLAGS[@]+"${SCRATCH_FLAGS[@]}"} "${TEST_FLAGS[@]}" --xunit-output "${xml_dir}/results.xml" 2>&1 | tee "${test_log}"; then
    rm -f "${test_log}"; rm -rf "${xml_dir}"
    fail "swift test"
fi

st_counts="$("${ROOT}/Scripts/xunit-summary.sh" "${xml_dir}/results-swift-testing.xml")" \
    || { rm -f "${test_log}"; rm -rf "${xml_dir}"; fail "xunit accounting (see above)"; }
rm -rf "${xml_dir}"
executed="$(printf '%s' "${st_counts}" | awk '{print $1}')"
failed="$(printf '%s' "${st_counts}" | awk '{print $2}')"
skipped="$(printf '%s' "${st_counts}" | awk '{print $3}')"

[ "${failed}" = "0" ] || { rm -f "${test_log}"; fail "the xUnit XML records ${failed} failures"; }
[ "${skipped}" = "0" ] || { rm -f "${test_log}"; fail "the xUnit XML records ${skipped} skipped tests (a skipped test is a failed test)"; }

# --- Gate 3: declared == executed -------------------------------------------------------------

declared=$(grep -rhoE --include='*.swift' '@Test[[:space:](]' "${PACKAGE_DIR}/Tests" 2>/dev/null \
    | wc -l | tr -d ' ')
[ "${declared:-0}" -gt 0 ] || { rm -f "${test_log}"; fail "zero @Test declarations found — the gate scanned nothing"; }
if [ "${executed}" -ne "${declared}" ]; then
    rm -f "${test_log}"
    fail "declared ${declared} tests but the runner executed ${executed}"
fi

# --- Gate 4: every loop step actually ran ------------------------------------------------------

readonly MARKERS=(
    "CORE-LOOP OPEN-OK fixture=${FIXTURE_IDENTITY} sha256=${FIXTURE_SHA256}"
    "CORE-LOOP CALIBRATE-OK actions=4 scale=1:50"
    "CORE-LOOP MEASURE-OK polyline=7.50 area=15.00 net=14.50"
    # areaTotal is the roof plane's net area only (15.00 outline - 0.50 opening). The cutout row
    # carries no quantity (ADR-0016 / ADR-0018); before those it read 15.50, the opening counted twice.
    "CORE-LOOP LEDGER-OK rows=4 lengthTotal=7.94 areaTotal=14.50"
    "CORE-LOOP EXPORT-OK csvActions=3 pdfActions=3"
    "CORE-LOOP GUARDS-OK filtered-labelled mixed-units-refused stale-recomputed"
    "CORE-LOOP SAVE-REOPEN-OK rows=4 identical"
    "CORE-LOOP UNDO-OK steps=6 hash-unchanged"
    "CORE-LOOP GUARD-UNCALIBRATED-OK refused-and-flagged"
    "CORE-LOOP GUARD-EXTREME-SCALE-OK confirmation-required"
)
for marker in "${MARKERS[@]}"; do
    if ! grep -qF "${marker}" "${test_log}"; then
        rm -f "${test_log}"
        fail "named proof obligation (no line matching '${marker}')"
    fi
done
rm -f "${test_log}"

# --- Gate 5: nothing skipped or compiled out ---------------------------------------------------

if grep -rqE 'XCTSkip|\.disabled\(|#if[[:space:]]+false' "${PACKAGE_DIR}/Tests" 2>/dev/null; then
    fail "a test is skipped or compiled out; a skipped test counts as failed here"
fi

printf '\nCORE_LOOP acceptance gate: %s tests executed, 0 failed, 0 skipped, all %s step markers present.\n' \
    "${executed}" "${#MARKERS[@]}"
printf 'Sign-off requires this gate green AND a maintainer'\''s own hands-on approval.\n'
exit 0
